const sceneData = $('Get Scene Details').first().json;
const castData = $('Get Cast List').all().map(item => item.json);
const weatherData = $('Get Weather').first().json;

// Format call sheet data
const callSheet = {
  project_title: sceneData.project_title || 'Unknown Project',
  scene_number: sceneData.scene_number,
  scene_name: sceneData.scene_name,
  location: {
    name: sceneData.location_name,
    address: sceneData.address,
    contact: sceneData.contact_name,
    phone: sceneData.contact_phone
  },
  weather: {
    temperature: Math.round(weatherData.main?.temp || 70),
    description: weatherData.weather?.[0]?.description || 'Unknown',
    humidity: weatherData.main?.humidity || 'Unknown'
  },
  cast: castData.map(actor => ({
    character: actor.name,
    actor: actor.first_name && actor.last_name ? `${actor.first_name} ${actor.last_name}` : 'TBD',
    phone: actor.phone || 'TBD',
    call_time: '6:00 AM', // This would be calculated based on scene schedule
    pickup_time: '5:30 AM'
  })),
  crew_call: '5:00 AM',
  wrap_estimate: '6:00 PM',
  safety_notes: [
    'All crew must wear safety vests on location',
    'First aid kit available with AD',
    'Emergency contact: 911'
  ],
  special_requirements: sceneData.special_requirements || 'None',
  generated_at: new Date().toISOString()
};

return { json: callSheet };
